 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Offensive lineup changes are highly correlated with other factors like opponent defense, game state, coaching strategy, and individual player talent/roles. Without robust controls (e.g., fixed effects for specific players or lineups), observed shot mix changes could be attributed to these confounders rather than the personnel change itself."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "The number of unique offensive lineup combinations, and the minutes played by each, can be highly sparse. Detecting statistically significant shifts in shot mix for specific lineup changes may require a very large sample size, and many combinations might lack sufficient data, as indicated by FAM:SF34 and FAM:SF-APPS-087."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Defining and reliably measuring 'shot mix' can be complex. Different categorizations (e.g., distance, shot type, initiator) might yield different results, and the sensitivity of these measures to personnel changes needs to be considered."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Team strategies, player roles, and league-wide shot tendencies can evolve over the three seasons of data, potentially confounding comparisons across different time periods or making older data less relevant to current effects."
  }
 ],
 "predicted_outcome": {
  "supported": 0.2,
  "rejected": 0.3,
  "untestable": 0.1,
  "artifact": 0.2,
  "uncertain": 0.2
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The average causal effect of changing offensive personnel on the distribution of shot types and locations (shot mix) per possession, controlling for game state and opponent characteristics. Specifically, the difference in mean shot mix metrics (e.g., rim attempt rate, 3pt attempt rate, mid-range attempt rate, drive rate) between possessions played by specific offensive lineups, relative to a baseline lineup or average.",
  "unit": "Offensive possession (from play-by-play data), aggregated by unique offensive lineup segments.",
  "sample": "All offensive possessions from NBA 2022-23, 2023-24, and 2024-25 regular seasons and playoffs. Filter for possessions where the offensive five is stable and identifiable. Consider a minimum possession threshold per lineup for inclusion (e.g., >50 possessions).",
  "power": "A power analysis will be conducted to determine the minimum detectable effect size for key shot mix components (e.g., 3PA rate, rim attempt rate) given the expected variance and sample sizes of lineup-level data. This will inform the choice of target effects (e.g., a 1-2 percentage point shift in 3PA rate). Historical evidence suggests effects might be small, so a high bar for statistical significance (e.g., p<0.01) with sufficient power will be needed to avoid inconclusive results.",
  "controls": "Use fixed effects for: 1) Offensive lineup (the specific five players on court). This is crucial to capture the 'personnel effect' directly. 2) Opponent lineup. 3) Game state (e.g., score differential, quarter, time remaining). 4) Team fixed effects. 5) Season fixed effects. Consider player-specific random effects to model individual tendencies. The primary outcome will be shot mix (e.g., proportion of possessions ending in a rim attempt, 3-point attempt, mid-range jumper, drive, post-up).",
  "falsification": "A falsification test could involve analyzing 'placebo' outcomes that should not be affected by offensive personnel changes (e.g., opponent turnover rate, or shot mix changes for non-offensive actions). If these also show significant shifts, it would indicate a flaw in the model or confounding. Additionally, test for effects of individual players on shot mix when they are not initiating the play, to ensure the effect is lineup-wide rather than solely initiator-driven.",
  "multiplicity": "Multiple outcome measures (different shot mix components) will be tested. Apply False Discovery Rate (FDR) correction (e.g., Benjamini-Hochberg) to p-values to account for multiple comparisons.",
  "decision_rule": "The research question aims to show the design 'can detect personnel effects'. A design will be considered successful if statistically significant (p<0.01 after FDR correction) and substantively meaningful changes (e.g., >1 percentage point shift) in at least two distinct components of shot mix are consistently observed across different offensive lineup changes, and these effects remain robust after rigorous confounding controls and falsification checks. Inconclusive results (weak effects, high p-values) or artifacts would lead to a 'rejected' or 'artifact' outcome.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs play-by-play, substitution rotation, starters, defensive matchup, box-score summary, and derived play-type possession records."
 }
}

